policies.inbound:






        ${b2c_client_id}


        https://${b2c_domain}/${b2c_tenant_id}/v2.0/



            .*







<set-variable name="userEmail" value="@{
    var jwt = context.Request.Headers.GetValueOrDefault("Authorization", "").Replace("Bearer ", "");
    if (string.IsNullOrEmpty(jwt)) return null;

    try {
        var base64 = jwt.Split('.')[1];
        var padded = base64.PadRight(base64.Length + (4 - base64.Length % 4) % 4, '=');
        var bytes = Convert.FromBase64String(padded);
        var json = System.Text.Encoding.UTF8.GetString(bytes);
        var token = Newtonsoft.Json.Linq.JObject.Parse(json);

        // B2C can return email in different claims
        var emails = token["emails"]?.ToString();
        if (!string.IsNullOrEmpty(emails)) return emails.Trim('[', ']', '"');

        return token["email"]?.ToString();
    } catch {
        return null;
    }
}" />



    @((string)context.Variables["userId"])


    @((string)context.Variables["userEmail"])






<rate-limit-by-key calls="100" 
                  renewal-period="60" 
                  counter-key="@(context.Request.Headers.GetValueOrDefault("X-User-ID", "anonymous"))" 
                  increment-condition="@(context.Response.StatusCode >= 200 && context.Response.StatusCode < 300)" />


<quota-by-key calls="10000" 
             renewal-period="86400" 
             counter-key="@(context.Subscription?.Key ?? "anonymous")" 
             increment-condition="@(context.Response.StatusCode >= 200 && context.Response.StatusCode < 300)" />





            Accept
            Accept-Charset
            Accept-Encoding
            Authorization
            *









    v1

return-response.set-body:
@{
                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("code", 429),
                                new JProperty("message", "Rate limit exceeded. Please try again in 60 seconds."),
                                new JProperty("requestId", context.Variables["requestId"]),
                                new JProperty("retryAfter", "60 seconds")
                            ))
                        ).ToString();
                    }

@{
                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("code", 429),
                                new JProperty("message", "Daily quota exceeded. Please upgrade your subscription or try again tomorrow."),
                                new JProperty("requestId", context.Variables["requestId"])
                            ))
                        ).ToString();
                    }

@{
                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("code", context.Response.StatusCode),
                                new JProperty("message", context.LastError?.Message ?? "An error occurred processing your request"),
                                new JProperty("requestId", context.Variables["requestId"]),
                                new JProperty("timestamp", DateTime.UtcNow.ToString("o"))
                            ))
                        ).ToString();
                    }
